query SearchShopPricingBySku($country: String! = "US", $skus: [String!]!, $pageInfo: ElasticSearchPageInput) {
  searchProducts(
    input: {storeType: ONLINE_STORE, country: $country, pageInfo: $pageInfo, filters: {skus: $skus}}
  ) {
    total
    data {
      ...SearchShopPricingChildProduct
      ...SearchShopPricingStandaloneProduct
      __typename
    }
    __typename
  }
}

fragment SearchShopPricingChildProduct on ChildProduct {
  sku
  price {
    listPrice {
      amount
      currency
      __typename
    }
    __typename
  }
  __typename
}

fragment SearchShopPricingStandaloneProduct on StandaloneProduct {
  sku
  price {
    listPrice {
      amount
      currency
      __typename
    }
    __typename
  }
  __typename
}

query SearchShopProductsBySkus($country: String! = "US", $skus: [String!]!, $pageInfo: ElasticSearchPageInput) {
  searchProducts(
    input: {storeType: ONLINE_STORE, country: $country, pageInfo: $pageInfo, filters: {skus: $skus}}
  ) {
    total
    size
    from
    data {
      ...SearchShopProductsChildProduct
      ...SearchShopProductsStandaloneProduct
      __typename
    }
    __typename
  }
}

fragment SearchShopProductsChildProduct on ChildProduct {
  _id: sku
  sku
  title
  brand
  rivianShopStatus
  price {
    listPrice {
      amount
      currency
      __typename
    }
    __typename
  }
  dimensionValues {
    name
    valueName
    localizedStrings
    __typename
  }
  channels
  channelAttributes {
    ...SearchShopProductsChannelAttribute
    __typename
  }
  __typename
}

fragment SearchShopProductsChannelAttribute on ChannelAttribute {
  attributeId
  name
  channel
  value
  __typename
}

fragment SearchShopProductsStandaloneProduct on StandaloneProduct {
  _id: sku
  sku
  title
  brand
  rivianShopStatus
  price {
    listPrice {
      amount
      currency
      __typename
    }
    __typename
  }
  channels
  channelAttributes {
    ...SearchShopProductsChannelAttribute
    __typename
  }
  __typename
}

query getVehicleChargingSchedules($vehicleId: String!) {
  getVehicle(id: $vehicleId) {
    chargingSchedules {
      weekDays
      startTime
      duration
      location {
        latitude
        longitude
      }
      amperage
      enabled
    }
  }
}

mutation setChargingSchedules($vehicleId: String!, $chargingSchedules: [InputChargingSchedule!]!) {
  setChargingSchedules(vehicleId: $vehicleId, chargingSchedules: $chargingSchedules) {
    __typename
    success
  }
}
